NSString *url = [NSString stringWithFormat:@"https://www.youtube.com/embed/watch?v=123456789"];
NSURL *urlConnection = [NSURL URLWithString:url];
NSHTTPCookie *cookie = [NSHTTPCookie initWithURL:[NSURL URLWithString:url]];

// Request the redirect
