```javascript
// P5.js (snowflake falling script)
let snowflake;

function setup() {
  createCanvas(400, 400);
  snowflake = createSprite(200, 300, 5, 5);
  snowflake.visible = false;
}

function draw() {
  background(255);

  // Create a single snowflake
  snowflake = createSprite(200, 300, 5, 5);
  snowflake.visible = false;

  // Add a small force to move the snowflake down
  push();
  translate(200, 300);
  rotate(10);
  snowflake.setVelocityY(-5);
  pop();

  // Wait for the snowflake to fall
  wait(100);

  // Check if the snowflake is visible
