    // If it disappears at the bottom, it reappears at the top
    if (snowflake.y < 300) {
      snowflake.visible = false;
      snowflake = createSprite(200, 300, 5, 5);
      snowflake.visible = true;
    }
  }

  // Draw the snowflake
  drawSprites();
}
