    // If it's an opening parenthesis
    if (char === '(') {
      dp[i] = dp[i - 1] + 1;
    } else if (char === ')') {
      dp[i] = dp[i - 1] - 1;
    }

    // If we are at the end of the string, check if it's valid
    if (i === newStr.length - 1) {
      count += dp[i];
    }
  }

  return count;
}

