  <meta charset="UTF-8">
  <title>Visitor Count Tracker</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      padding: 20px;
    }
  </style>
</head>
<body>

  <h1>Visitor Count Tracker</h1>

  <!-- Display visitor count -->
  <p>Current Visitor Count: <span id="visitors">0</span></p>

  <!-- Add a new visitor button -->
  <button onclick="addVisitor()">Add New Visitor</button>

  <script>
    // Initialize localStorage
    function initializeLocalStorage() {
      const dailyVisits = localStorage.getItem('dailyVisits');
      const monthlyVisits = localStorage.getItem('monthlyVisits');

      if (dailyVisits) {
        document.getElementById("visitors").textContent = dailyVisits;
      }

      if (monthlyVisits) {
        document.getElementById("visitors").textContent = monthlyVisits;
      }
